CREATE TABLE IF NOT EXISTS classes (id SERIAL PRIMARY KEY, name TEXT NOT NULL, section TEXT NOT NULL, academic_year TEXT NOT NULL, UNIQUE(name,section,academic_year));
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','teacher','accountant','student','parent')), active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS students (id SERIAL PRIMARY KEY, admission_no TEXT NOT NULL UNIQUE, name TEXT NOT NULL, date_of_birth DATE, gender TEXT, class_id INT NOT NULL REFERENCES classes(id), roll_no TEXT NOT NULL, guardian_name TEXT, guardian_phone TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), user_id INT UNIQUE REFERENCES users(id), UNIQUE(class_id,roll_no));
CREATE TABLE IF NOT EXISTS student_enrollments (id SERIAL PRIMARY KEY, student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE, class_id INT NOT NULL REFERENCES classes(id), UNIQUE(student_id,class_id));
CREATE OR REPLACE FUNCTION remember_student_class() RETURNS TRIGGER AS $$ BEGIN INSERT INTO student_enrollments(student_id,class_id) VALUES(NEW.id,NEW.class_id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS remember_student_class_trigger ON students;
CREATE TRIGGER remember_student_class_trigger AFTER INSERT OR UPDATE OF class_id ON students FOR EACH ROW EXECUTE FUNCTION remember_student_class();
INSERT INTO student_enrollments(student_id,class_id) SELECT id,class_id FROM students ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS staff (id SERIAL PRIMARY KEY, name TEXT NOT NULL, employee_no TEXT NOT NULL UNIQUE, designation TEXT NOT NULL, phone TEXT, user_id INT UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS parent_students (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE, UNIQUE(user_id,student_id));
CREATE TABLE IF NOT EXISTS teacher_classes (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, class_id INT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, UNIQUE(user_id,class_id));
CREATE TABLE IF NOT EXISTS attendance (id SERIAL PRIMARY KEY, student_id INT NOT NULL REFERENCES students(id), date DATE NOT NULL, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), note TEXT, UNIQUE(student_id,date));
ALTER TABLE attendance ADD COLUMN IF NOT EXISTS class_id INT REFERENCES classes(id);
UPDATE attendance a SET class_id=s.class_id FROM students s WHERE a.student_id=s.id AND a.class_id IS NULL;
ALTER TABLE attendance ALTER COLUMN class_id SET NOT NULL;
CREATE OR REPLACE FUNCTION set_attendance_class() RETURNS TRIGGER AS $$ BEGIN IF TG_OP='INSERT' OR NEW.student_id IS DISTINCT FROM OLD.student_id THEN SELECT class_id INTO NEW.class_id FROM students WHERE id=NEW.student_id; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS set_attendance_class_trigger ON attendance;
CREATE TRIGGER set_attendance_class_trigger BEFORE INSERT OR UPDATE OF student_id ON attendance FOR EACH ROW EXECUTE FUNCTION set_attendance_class();
CREATE TABLE IF NOT EXISTS staff_attendance (id SERIAL PRIMARY KEY, staff_id INT NOT NULL REFERENCES staff(id), date DATE NOT NULL, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), note TEXT, UNIQUE(staff_id,date));
CREATE TABLE IF NOT EXISTS fee_structures (id SERIAL PRIMARY KEY, class_id INT NOT NULL REFERENCES classes(id), name TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount >= 0), due_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id SERIAL PRIMARY KEY, student_id INT NOT NULL REFERENCES students(id), fee_structure_id INT NOT NULL REFERENCES fee_structures(id), amount NUMERIC(12,2) NOT NULL CHECK(amount >= 0), due_date DATE NOT NULL, UNIQUE(student_id,fee_structure_id));
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, invoice_id INT NOT NULL REFERENCES invoices(id), amount NUMERIC(12,2) NOT NULL CHECK(amount > 0), paid_on DATE NOT NULL, method TEXT NOT NULL CHECK(method IN ('cash','bank')), reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS exams (id SERIAL PRIMARY KEY, class_id INT NOT NULL REFERENCES classes(id), name TEXT NOT NULL, subject TEXT NOT NULL, exam_date DATE NOT NULL, max_marks NUMERIC(6,2) NOT NULL CHECK(max_marks > 0));
CREATE TABLE IF NOT EXISTS marks (id SERIAL PRIMARY KEY, exam_id INT NOT NULL REFERENCES exams(id), student_id INT NOT NULL REFERENCES students(id), marks NUMERIC(6,2) NOT NULL CHECK(marks >= 0), UNIQUE(exam_id,student_id));
CREATE TABLE IF NOT EXISTS grade_bands (id SERIAL PRIMARY KEY, label TEXT NOT NULL UNIQUE, minimum NUMERIC(5,2) NOT NULL UNIQUE CHECK(minimum >= 0 AND minimum <= 100));
CREATE TABLE IF NOT EXISTS timetable (id SERIAL PRIMARY KEY, class_id INT NOT NULL REFERENCES classes(id), teacher_id INT NOT NULL REFERENCES staff(id), substitute_id INT REFERENCES staff(id), day TEXT NOT NULL CHECK(day IN ('Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday')), start_time TIME NOT NULL, end_time TIME NOT NULL CHECK(end_time > start_time), subject TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY, student_id INT NOT NULL REFERENCES students(id), original_name TEXT NOT NULL, storage_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, actor_id INT REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INT, at TIMESTAMPTZ NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS students_class_idx ON students(class_id);
CREATE INDEX IF NOT EXISTS documents_student_idx ON documents(student_id);
CREATE INDEX IF NOT EXISTS invoices_student_idx ON invoices(student_id);
CREATE INDEX IF NOT EXISTS payments_invoice_idx ON payments(invoice_id);
CREATE INDEX IF NOT EXISTS exams_class_idx ON exams(class_id);
CREATE INDEX IF NOT EXISTS marks_student_idx ON marks(student_id);
CREATE INDEX IF NOT EXISTS timetable_class_idx ON timetable(class_id);
CREATE INDEX IF NOT EXISTS enrollments_class_idx ON student_enrollments(class_id,student_id);
